using System;
using System.Data;
using System.Data.SQLite;
using System.Drawing;
using System.Windows.Forms;
using System.Linq;
using ClinicQueueSystem.Data;
using ClinicQueueSystem.Services;

namespace ClinicQueueSystem.Forms
{
    public class AdminForm : Form
    {
        readonly int userId; readonly string userName; TabControl tabs=new TabControl();
        public AdminForm(int id,string name){userId=id;userName=name;Text="Clinic Queue System - Admin";Width=1100;Height=700;StartPosition=FormStartPosition.CenterParent;Build();}
        void Build(){tabs.Dock=DockStyle.Fill;Controls.Add(tabs);AddSimple("Departments","departments",new[]{"code","name","default_price","description","display_order","active"});AddDoctors();AddSimple("Shifts","shifts",new[]{"name","start_time","end_time","display_order","active"});AddSimple("Counters","counters",new[]{"counter_number","name","location","active"});AddSimple("Printers","printers",new[]{"name","system_printer_name","connection_type","paper_width","ip_address","port","active"});AddUsers();AddSettings();AddTickets();AddAudit();}
        void AddSimple(string title,string table,string[] fields){var page=new TabPage(title);var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};var panel=new Panel{Dock=DockStyle.Top,Height=45};var add=new Button{Text="ADD",Left=5,Top=8,Width=80};var edit=new Button{Text="EDIT",Left=90,Top=8,Width=80};var del=new Button{Text="DELETE/DEACTIVATE",Left=175,Top=8,Width=150};panel.Controls.AddRange(new Control[]{add,edit,del});page.Controls.Add(grid);page.Controls.Add(panel);tabs.TabPages.Add(page);void Refresh(){grid.DataSource=Database.Query("SELECT * FROM "+table+" ORDER BY id DESC");}Refresh();add.Click+=(s,e)=>EditRecord(table,fields,null,Refresh);edit.Click+=(s,e)=>{if(grid.CurrentRow!=null)EditRecord(table,fields,Convert.ToInt64(grid.CurrentRow.Cells["id"].Value),Refresh);};del.Click+=(s,e)=>{if(grid.CurrentRow==null)return;long id=Convert.ToInt64(grid.CurrentRow.Cells["id"].Value);if(table=="tickets")return;string sql=table=="users"||table=="departments"||table=="doctors"||table=="shifts"||table=="counters"?"UPDATE "+table+" SET active=0 WHERE id=@id":"DELETE FROM "+table+" WHERE id=@id";using(var c=Database.Connection())Database.ExecuteNonQuery(c,sql,new SQLiteParameter("@id",id));Refresh();};}
        void AddUsers(){
            var page=new TabPage("Users");
            var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
            var panel=new Panel{Dock=DockStyle.Top,Height=45};
            var add=new Button{Text="ADD USER",Left=5,Top=8,Width=100};
            var edit=new Button{Text="EDIT",Left=110,Top=8,Width=80};
            var deact=new Button{Text="DEACTIVATE",Left=195,Top=8,Width=100};
            panel.Controls.AddRange(new Control[]{add,edit,deact}); page.Controls.Add(grid); page.Controls.Add(panel); tabs.TabPages.Add(page);
            Action refresh=()=>grid.DataSource=Database.Query("SELECT id,username,full_name,role,active,created_at FROM users ORDER BY id DESC"); refresh();
            add.Click+=(s,e)=>EditUser(null,refresh); edit.Click+=(s,e)=>{if(grid.CurrentRow!=null)EditUser(Convert.ToInt64(grid.CurrentRow.Cells["id"].Value),refresh);};
            deact.Click+=(s,e)=>{if(grid.CurrentRow==null)return;using(var c=Database.Connection())Database.ExecuteNonQuery(c,"UPDATE users SET active=0,updated_at=@u WHERE id=@id",new SQLiteParameter("@u",DateTime.Now.ToString("s")),new SQLiteParameter("@id",grid.CurrentRow.Cells["id"].Value));refresh();};
        }
        void EditUser(long? id,Action refresh){
            using(var f=new Form{Text=id.HasValue?"Edit User":"Add User",Width=430,Height=330,StartPosition=FormStartPosition.CenterParent}){
                var username=new TextBox(); var name=new TextBox(); var password=new TextBox{UseSystemPasswordChar=true}; var role=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList}; role.Items.AddRange(new object[]{"ADMIN","RECEPTIONIST","SUPERVISOR"}); role.SelectedIndex=1;
                if(id.HasValue){var t=Database.Query("SELECT username,full_name,role FROM users WHERE id="+id.Value);if(t.Rows.Count>0){username.Text=t.Rows[0][0].ToString();username.ReadOnly=true;name.Text=t.Rows[0][1].ToString();role.SelectedItem=t.Rows[0][2].ToString();}}
                var g=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(15),ColumnCount=2,RowCount=5};
                g.Controls.Add(new Label{Text="Username"},0,0);g.Controls.Add(username,1,0);g.Controls.Add(new Label{Text="Full Name"},0,1);g.Controls.Add(name,1,1);g.Controls.Add(new Label{Text=id.HasValue?"New Password (optional)":"Password"},0,2);g.Controls.Add(password,1,2);g.Controls.Add(new Label{Text="Role"},0,3);g.Controls.Add(role,1,3);
                var save=new Button{Text="SAVE",Dock=DockStyle.Bottom};f.Controls.Add(g);f.Controls.Add(save);
                save.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(username.Text)||string.IsNullOrWhiteSpace(name.Text)||(!id.HasValue&&string.IsNullOrWhiteSpace(password.Text))){MessageBox.Show("Username, name and password are required for a new user.");return;}using(var c=Database.Connection()){
                    if(id.HasValue){if(string.IsNullOrWhiteSpace(password.Text))Database.ExecuteNonQuery(c,"UPDATE users SET full_name=@n,role=@r,updated_at=@u WHERE id=@id",new SQLiteParameter("@n",name.Text),new SQLiteParameter("@r",role.Text),new SQLiteParameter("@u",DateTime.Now.ToString("s")),new SQLiteParameter("@id",id.Value));else Database.ExecuteNonQuery(c,"UPDATE users SET full_name=@n,role=@r,password_hash=@p,updated_at=@u WHERE id=@id",new SQLiteParameter("@n",name.Text),new SQLiteParameter("@r",role.Text),new SQLiteParameter("@p",PasswordHasher.Hash(password.Text)),new SQLiteParameter("@u",DateTime.Now.ToString("s")),new SQLiteParameter("@id",id.Value));}
                    else Database.ExecuteNonQuery(c,"INSERT INTO users(username,password_hash,full_name,role,created_at) VALUES(@u,@p,@n,@r,@d)",new SQLiteParameter("@u",username.Text),new SQLiteParameter("@p",PasswordHasher.Hash(password.Text)),new SQLiteParameter("@n",name.Text),new SQLiteParameter("@r",role.Text),new SQLiteParameter("@d",DateTime.Now.ToString("s")));
                }f.Close();refresh();};f.ShowDialog(this);
            }
        }
        void AddDoctors(){var page=new TabPage("Doctors");var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};var panel=new Panel{Dock=DockStyle.Top,Height=45};var add=new Button{Text="ADD DOCTOR",Left=5,Top=8,Width=110};var edit=new Button{Text="EDIT",Left=120,Top=8,Width=80};var deact=new Button{Text="DEACTIVATE",Left=205,Top=8,Width=100};panel.Controls.AddRange(new Control[]{add,edit,deact});page.Controls.Add(grid);page.Controls.Add(panel);tabs.TabPages.Add(page);Action refresh=()=>grid.DataSource=Database.Query("SELECT d.id,d.name,d.room_number,d.default_price,d.specialization,d.active,GROUP_CONCAT(dep.name, ', ') departments FROM doctors d LEFT JOIN doctor_departments dd ON dd.doctor_id=d.id LEFT JOIN departments dep ON dep.id=dd.department_id GROUP BY d.id ORDER BY d.name");refresh();add.Click+=(s,e)=>EditDoctor(null,refresh);edit.Click+=(s,e)=>{if(grid.CurrentRow!=null)EditDoctor(Convert.ToInt64(grid.CurrentRow.Cells["id"].Value),refresh);};deact.Click+=(s,e)=>{if(grid.CurrentRow==null)return;using(var c=Database.Connection())Database.ExecuteNonQuery(c,"UPDATE doctors SET active=0 WHERE id=@id",new SQLiteParameter("@id",grid.CurrentRow.Cells["id"].Value));refresh();};}
        void EditDoctor(long? id,Action refresh){using(var f=new Form{Text=id.HasValue?"Edit Doctor":"Add Doctor",Width=450,Height=400,StartPosition=FormStartPosition.CenterParent}){var name=new TextBox();var room=new TextBox();var spec=new TextBox();var price=new NumericUpDown{Maximum=1000000,DecimalPlaces=2};var dep=new CheckedListBox{Dock=DockStyle.Fill};var t=Database.Query("SELECT id,name FROM departments WHERE active=1 ORDER BY name");foreach(DataRow r in t.Rows)dep.Items.Add(new Item(r["name"].ToString(),Convert.ToInt32(r["id"])));if(id.HasValue){var x=Database.Query("SELECT * FROM doctors WHERE id="+id.Value);if(x.Rows.Count>0){name.Text=x.Rows[0]["name"].ToString();room.Text=x.Rows[0]["room_number"].ToString();spec.Text=x.Rows[0]["specialization"].ToString();price.Value=x.Rows[0]["default_price"]==DBNull.Value?0:Convert.ToDecimal(x.Rows[0]["default_price"]);var ds=Database.Query("SELECT department_id FROM doctor_departments WHERE doctor_id="+id.Value);foreach(DataRow r in ds.Rows)for(int i=0;i<dep.Items.Count;i++)if(((Item)dep.Items[i]).Id==Convert.ToInt32(r[0]))dep.SetItemChecked(i,true);}}var g=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(15),ColumnCount=2,RowCount=5};g.Controls.Add(new Label{Text="Name"},0,0);g.Controls.Add(name,1,0);g.Controls.Add(new Label{Text="Room"},0,1);g.Controls.Add(room,1,1);g.Controls.Add(new Label{Text="Specialization"},0,2);g.Controls.Add(spec,1,2);g.Controls.Add(new Label{Text="Default Price"},0,3);g.Controls.Add(price,1,3);g.Controls.Add(new Label{Text="Departments"},0,4);g.Controls.Add(dep,1,4);var save=new Button{Text="SAVE",Dock=DockStyle.Bottom};f.Controls.Add(g);f.Controls.Add(save);save.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(name.Text)){MessageBox.Show("Name required");return;}using(var c=Database.Connection()){if(id.HasValue)Database.ExecuteNonQuery(c,"UPDATE doctors SET name=@n,room_number=@r,default_price=@p,specialization=@s,updated_at=@u WHERE id=@id",new SQLiteParameter("@n",name.Text),new SQLiteParameter("@r",room.Text),new SQLiteParameter("@p",price.Value),new SQLiteParameter("@s",spec.Text),new SQLiteParameter("@u",DateTime.Now.ToString("s")),new SQLiteParameter("@id",id.Value));else Database.ExecuteNonQuery(c,"INSERT INTO doctors(name,room_number,default_price,specialization,created_at) VALUES(@n,@r,@p,@s,@u)",new SQLiteParameter("@n",name.Text),new SQLiteParameter("@r",room.Text),new SQLiteParameter("@p",price.Value),new SQLiteParameter("@s",spec.Text),new SQLiteParameter("@u",DateTime.Now.ToString("s")));long did=id??Convert.ToInt64(Database.Scalar(c,"SELECT last_insert_rowid()"));Database.ExecuteNonQuery(c,"DELETE FROM doctor_departments WHERE doctor_id=@id",new SQLiteParameter("@id",did));foreach(Item it in dep.CheckedItems)Database.ExecuteNonQuery(c,"INSERT INTO doctor_departments(doctor_id,department_id) VALUES(@d,@dep)",new SQLiteParameter("@d",did),new SQLiteParameter("@dep",it.Id));}f.DialogResult=DialogResult.OK;f.Close();refresh();};f.ShowDialog(this);}}
        void EditRecord(string table,string[] fields,long? id,Action refresh){using(var f=new Form{Text=id.HasValue?"Edit "+table:"Add "+table,Width=520,Height=500,StartPosition=FormStartPosition.CenterParent}){var g=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(15),ColumnCount=2};var inputs=new System.Collections.Generic.Dictionary<string,Control>();DataRow row=null;if(id.HasValue){var t=Database.Query("SELECT * FROM "+table+" WHERE id="+id.Value);if(t.Rows.Count>0)row=t.Rows[0];}foreach(string field in fields){Control c;if(field=="active"){c=new CheckBox{Checked=row==null||Convert.ToInt32(row[field])==1};}else if(field.Contains("price")){c=new NumericUpDown{Maximum=1000000,DecimalPlaces=2,Value=row==null?0:Convert.ToDecimal(row[field])};}else if(field=="description"||field=="location"){c=new TextBox{Multiline=true,Height=50,Text=row==null?"":row[field].ToString()};}else{c=new TextBox{Text=row==null?"":row[field].ToString()};}g.RowStyles.Add(new RowStyle(SizeType.AutoSize));g.Controls.Add(new Label{Text=field,AutoSize=true},0,g.RowCount);g.Controls.Add(c,1,g.RowCount);g.RowCount++;inputs[field]=c;}var save=new Button{Text="SAVE",Dock=DockStyle.Bottom};f.Controls.Add(g);f.Controls.Add(save);save.Click+=(s,e)=>{using(var c=Database.Connection()){if(id.HasValue){var sets=string.Join(",",fields.Select(x=>x+"=@"+x));var ps=new System.Collections.Generic.List<SQLiteParameter>();foreach(string field in fields)ps.Add(new SQLiteParameter("@"+field,Value(inputs[field])));ps.Add(new SQLiteParameter("@id",id.Value));Database.ExecuteNonQuery(c,"UPDATE "+table+" SET "+sets+" WHERE id=@id",ps.ToArray());}else{var cols=string.Join(",",fields);var vals=string.Join(",",fields.Select(x=>"@"+x));var ps=new System.Collections.Generic.List<SQLiteParameter>();foreach(string field in fields)ps.Add(new SQLiteParameter("@"+field,Value(inputs[field])));Database.ExecuteNonQuery(c,"INSERT INTO "+table+"("+cols+") VALUES("+vals+")",ps.ToArray());}}f.Close();refresh();};f.ShowDialog(this);}}
        object Value(Control c){if(c is CheckBox)return ((CheckBox)c).Checked?1:0;if(c is NumericUpDown)return ((NumericUpDown)c).Value;return c.Text;}
        void AddSettings(){var page=new TabPage("Settings");var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,DataSource=Database.Query("SELECT key,value FROM settings ORDER BY key")};var b=new Button{Text="EDIT SELECTED",Dock=DockStyle.Bottom,Height=40};page.Controls.Add(grid);page.Controls.Add(b);tabs.TabPages.Add(page);b.Click+=(s,e)=>{if(grid.CurrentRow==null)return;string key=grid.CurrentRow.Cells["key"].Value.ToString();string value=Microsoft.VisualBasic.Interaction.InputBox("Value",key,grid.CurrentRow.Cells["value"].Value.ToString());using(var c=Database.Connection())Database.ExecuteNonQuery(c,"INSERT OR REPLACE INTO settings(key,value) VALUES(@k,@v)",new SQLiteParameter("@k",key),new SQLiteParameter("@v",value));grid.DataSource=Database.Query("SELECT key,value FROM settings ORDER BY key");};}
        void AddTickets(){var page=new TabPage("Tickets");var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,DataSource=Database.Query("SELECT t.id,t.ticket_number,t.ticket_date,t.ticket_time,d.name department,do.name doctor,s.name shift,t.price,t.status,t.print_count FROM tickets t JOIN departments d ON d.id=t.department_id LEFT JOIN doctors do ON do.id=t.doctor_id JOIN shifts s ON s.id=t.shift_id ORDER BY t.id DESC")};page.Controls.Add(grid);tabs.TabPages.Add(page);}
        void AddAudit(){var page=new TabPage("Audit Log");var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,DataSource=Database.Query("SELECT a.id,a.created_at,u.username,a.action,a.entity_type,a.entity_id,a.description FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC")};page.Controls.Add(grid);tabs.TabPages.Add(page);}
        class Item{public string Name;public int Id;public Item(string n,int i){Name=n;Id=i;}public override string ToString(){return Name;}}
    }
}
